/* Make only the active premium IPTV test card clickable as a card.
 *
 * The premium/original source links and every other interactive control keep
 * their own behavior. A click on the non-interactive body of the test card
 * follows the premium IPTV link already generated by iptv-auto.js.
 */
(function () {
  "use strict";

  const CARD_SELECTOR = ".match-card";
  const PREMIUM_LINK_SELECTOR =
    '.iptv-premium-test-toggle .watch-source-toggle__opt--premium[data-iptv-premium-test="1"]';
  const INTERACTIVE_SELECTOR = [
    "a",
    "button",
    "input",
    "select",
    "textarea",
    "summary",
    "details",
    '[role="button"]',
    '[role="link"]',
    '[contenteditable="true"]',
    ".match-panel",
    ".match-foot",
  ].join(",");

  function premiumLink(card) {
    const link = card?.querySelector?.(PREMIUM_LINK_SELECTOR);
    return link && !link.hidden ? link : null;
  }

  function isModifiedPrimaryClick(event) {
    return event.button > 0 || event.metaKey || event.ctrlKey || event.shiftKey || event.altKey;
  }

  function shouldIgnoreTarget(target, card) {
    if (!target?.closest) return true;
    const interactive = target.closest(INTERACTIVE_SELECTOR);
    return Boolean(interactive && card.contains(interactive));
  }

  function markPremiumCards(root) {
    const scope = root?.querySelectorAll ? root : document;
    for (const toggle of scope.querySelectorAll(".iptv-premium-test-toggle")) {
      const card = toggle.closest(CARD_SELECTOR);
      if (!card || !premiumLink(card)) continue;
      card.classList.add("iptv-premium-card-clickable");
      card.dataset.iptvPremiumCard = "1";
    }
  }

  function handleCardClick(event) {
    if (isModifiedPrimaryClick(event)) return;
    const target = event.target;
    const card = target?.closest?.(`${CARD_SELECTOR}[data-iptv-premium-card="1"]`);
    if (!card || shouldIgnoreTarget(target, card)) return;

    const link = premiumLink(card);
    if (!link?.href) return;
    window.location.assign(link.href);
  }

  function installCursorStyle() {
    if (document.getElementById("iptv-premium-card-click-style")) return;
    const style = document.createElement("style");
    style.id = "iptv-premium-card-click-style";
    style.textContent =
      ".match-card.iptv-premium-card-clickable{cursor:pointer}.match-card.iptv-premium-card-clickable .match-foot{cursor:default}";
    document.head?.appendChild(style);
  }

  function init() {
    installCursorStyle();
    markPremiumCards(document);
    document.addEventListener("click", handleCardClick);

    const observer = new MutationObserver((mutations) => {
      if (mutations.some((mutation) => mutation.type === "childList" && mutation.addedNodes.length)) {
        markPremiumCards(document);
      }
    });
    observer.observe(document.documentElement, { childList: true, subtree: true });
  }

  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", init, { once: true });
  } else {
    init();
  }
})();
